<?php
require_once __DIR__.'/../includes/certificate-auth.php';
    $user=fleet_cert_require_user();fleet_cert_require_permission($user,'page.source-operations');
try {
    $db=fleet_db();$rows=$db->query("SELECT s.source_code,sh.sheet_name,v.source_row_number,v.raw_data,v.captured_at FROM spreadsheet_source_row_versions v JOIN spreadsheet_sheets sh ON sh.id=v.sheet_id JOIN spreadsheet_sync_runs r ON r.id=v.sync_run_id JOIN spreadsheet_sources s ON s.id=r.source_id WHERE v.sync_run_id IN (SELECT MAX(id) FROM spreadsheet_sync_runs WHERE run_status='SUCCESS' GROUP BY source_id) ORDER BY sh.sheet_name,v.source_row_number")->fetchAll();
    $tracking=[];$geofences=[];$trackingObservations=[];$dash=[];$flatbedStatus=[];$tankerStatus=[];$registered21=['tanker_rows'=>0,'flatbed_rows'=>0];$it21=['consolidated_tanker_list_rows'=>0,'independent_tanker_list_rows'=>0,'consolidated_flatbed_list_rows'=>0,'independent_flatbed_list_rows'=>0];
    foreach($rows as $r){$cells=json_decode((string)$r['raw_data'],true)?:[];$sheet=$r['sheet_name'];$row=(int)$r['source_row_number'];
        if($r['source_code']==='NGWERERE_21MILES'&&$sheet==='Ngwerere'&&$row>1){$status=trim((string)($cells[1]??''));$category=preg_match('/^parking\b/i',$status)?'Parking':(preg_match('/^no connection/i',$status)?'No Connection':(preg_match('/\b(in trip|moving)\b/i',$status)?'In Trip / Moving':($status!==''?'Other':'Unknown')));$geo=trim((string)($cells[2]??''));$identifier=trim((string)($cells[0]??''));if($identifier!=='')$trackingObservations[]=['identifier'=>$identifier,'status'=>$status,'category'=>$category,'location'=>$geo,'source_row_number'=>$row,'captured_at'=>$r['captured_at']];$tracking[$category]=($tracking[$category]??0)+1;if($geo!=='')$geofences[$geo]=($geofences[$geo]??0)+1;}
