        if($r['source_code']==='CONSOLIDATED_TRUCKS'&&$sheet==='Ngwerere_Tankers_status'&&$row>=3&&(trim((string)($cells[2]??''))!==''||trim((string)($cells[3]??''))!=='')){$status=trim((string)($cells[4]??''));$status=$status!==''?$status:'Unknown';$tankerStatus[$status]=($tankerStatus[$status]??0)+1;}
        if($r['source_code']==='CONSOLIDATED_TRUCKS'&&$sheet==='Ngwerere_Flatbeds_Status'&&$row>=3&&(trim((string)($cells[2]??''))!==''||trim((string)($cells[3]??''))!=='')){$status=trim((string)($cells[4]??''));$status=$status!==''?$status:'Unknown';$flatbedStatus[$status]=($flatbedStatus[$status]??0)+1;}
        if($r['source_code']==='NGWERERE_21MILES'&&$sheet==='Registered_21Miles'&&$row>=3){if(trim((string)($cells[0]??''))!==''||trim((string)($cells[1]??''))!=='')$registered21['tanker_rows']++;if(trim((string)($cells[3]??''))!==''||trim((string)($cells[4]??''))!=='')$registered21['flatbed_rows']++;}
        if($row>=2&&trim((string)($cells[0]??''))!==''){
            if($r['source_code']==='CONSOLIDATED_TRUCKS'&&$sheet==='21Miles_Tankers_Unregistered')$it21['consolidated_tanker_list_rows']++;
            if($r['source_code']==='NGWERERE_21MILES'&&$sheet==='Unregistered_21Miles')$it21['independent_tanker_list_rows']++;
            if($r['source_code']==='CONSOLIDATED_TRUCKS'&&$sheet==='21Miles_Flatbed_Unregistered')$it21['consolidated_flatbed_list_rows']++;
