        }
    }
    $confirmedTypeCounts=$db->query("SELECT t.type_code,COUNT(*) AS n FROM assets a JOIN asset_types t ON t.id=a.asset_type_id WHERE a.is_active=1 GROUP BY t.type_code")->fetchAll();$confirmedMap=['HORSE'=>0,'TANKER'=>0,'FLATBED'=>0];foreach($confirmedTypeCounts as $ct){$kind=match($ct['type_code']){'TRUCK_HEAD'=>'HORSE','TANKER_TRAILER'=>'TANKER','FLATBED_TRAILER'=>'FLATBED',default=>null};if($kind!==null)$confirmedMap[$kind]=(int)$ct['n'];}$confirmedTotal=array_sum($confirmedMap);$confirmedFleet=[];foreach(['HORSE'=>'Horse','TANKER'=>'Tanker','FLATBED'=>'Flatbed'] as $code=>$label)$confirmedFleet[]=['type'=>$label,'count'=>$confirmedMap[$code],'percent'=>$confirmedTotal?round(100*$confirmedMap[$code]/$confirmedTotal,1):0];
