    $flatbedTotal=array_sum($flatbedStatus);$flatbedRows=[];foreach($flatbedStatus as $status=>$count)$flatbedRows[]=['status'=>$status,'count'=>$count,'percent'=>$flatbedTotal?round(100*$count/$flatbedTotal,1):0];$tankerTotal=array_sum($tankerStatus);$tankerRows=[];foreach($tankerStatus as $status=>$count)$tankerRows[]=['status'=>$status,'count'=>$count,'percent'=>$tankerTotal?round(100*$count/$tankerTotal,1):0];
    $sourceChanges=table_exists($db,'spreadsheet_source_change_log')?$db->query("SELECT l.id,l.change_type,l.previous_source_row_number,l.source_row_number,l.previous_data,l.new_data,l.detected_at,l.decision_status,l.decision_note,l.decided_at,s.source_name,sh.sheet_name FROM spreadsheet_source_change_log l JOIN spreadsheet_sources s ON s.id=l.source_id JOIN spreadsheet_sheets sh ON sh.id=l.sheet_id ORDER BY l.detected_at DESC,l.id DESC LIMIT 100")->fetchAll():[];
    foreach($sourceChanges as &$change){$change['previous_data']=$change['previous_data']?json_decode($change['previous_data'],true):null;$change['new_data']=$change['new_data']?json_decode($change['new_data'],true):null;}unset($change);
    json_response(['ok'=>true,'confirmed_app_fleet'=>['total'=>$confirmedTotal,'by_type'=>$confirmedFleet],'tracking_total'=>$trackingTotal,'tracking_status'=>$statusRows,'top_geofences'=>$top,'tracking_observations'=>$trackingObservations,'geofenced_total'=>array_sum($geofences),'without_geofence_total'=>max(0,$trackingTotal-array_sum($geofences)),'flatbed_status_total'=>$flatbedTotal,'flatbed_status'=>$flatbedRows,'tanker_status_total'=>$tankerTotal,'tanker_status'=>$tankerRows,'source_dashboard_metrics'=>$dashboardMetrics,'registered_21miles_source_rows'=>$registered21,'unregistered_21miles_it_list_rows'=>$it21,'source_changes'=>$sourceChanges,'can_review_deletions'=>fleet_cert_user_can($user,'source_changes.approve'),'notes'=>['Flatbed status is read from Consolidated Trucks / Ngwerere_Flatbeds_Status.','Tanker status is read from Consolidated Trucks / Ngwerere_Tankers_status.','Tracking status and geofence counts are time-specific observations from the Ngwerere tracking worksheet.','The spreadsheet Dashboard figures are shown as source-reported and unverified; they conflict with the row-level register.','21 Miles IT list rows and Registered_21Miles rows are source observations, not a validated physical fleet total.']]);
